$string['settings:rag_return_scope'] = 'Zakres zwracanych wyników wyszukiwania';
$string['settings:rag_return_scope_desc'] = 'Co ma zostać wstawione dla każdego znalezionego trafienia. "chunk" (domyślnie) wstawia dopasowany fragment o długości ok. 400 słów. "window" wstawia dopasowany fragment wraz z sąsiednimi fragmentami z tej samej strony. "page" wstawia całą stronę modułu, do której należy trafienie. window/page pomagają, gdy odpowiedź obejmuje całą stronę, kosztem większego prompta.';
$string['settings:rag_window_size'] = 'Rozmiar okna wyszukiwania';
$string['settings:rag_window_size_desc'] = 'Dla zakresu zwracania "window": liczba sąsiednich fragmentów uwzględnianych po każdej stronie dopasowanego fragmentu. Domyślnie 1.';
$string['settings:rag_parent_max_chars'] = 'Limit fragmentu nadrzędnego (znaki)';
$string['settings:rag_parent_max_chars_desc'] = 'Maksymalna liczba znaków dla rozszerzonego fragmentu window/page. Strony przekraczające limit są zastępowane fragmentem window, a następnie pojedynczym fragmentem (chunk). Domyślnie 6000.';
$string['settings:rag_enabled'] = 'Włącz RAG (wyszukiwanie semantyczne)';
$string['settings:rag_enabled_desc'] = 'Gdy włączone, korepetytor AI używa wyszukiwania semantycznego, aby pobrać dla każdego zapytania istotne treści kursu, zamiast wstawiać całą treść do promptu systemowego.';
$string['settings:rag_heading'] = 'RAG / wyszukiwanie semantyczne';
$string['settings:rag_heading_desc'] = 'Retrieval-Augmented Generation: indeksuje treści kursu jako embeddingi i pobiera w momencie zapytania tylko najtrafniejsze fragmenty. Zmniejsza zużycie tokenów i obsługuje wszystkie rodzaje treści. Wymaga API embeddingów.';
$string['settings:rag_topk'] = 'Fragmenty Top-K';
$string['settings:rag_topk_desc'] = 'Number of most relevant chunks to retrieve per user query and inject into the system prompt.';
$string['settings:realtime_apikey'] = 'OpenAI API Key (Voice & TTS)';
