// v4.4.0: course-page CSP setting.
$string['settings:csp_course_pages_mode'] = 'Content-Security-Policy na stronach kursu';
$string['settings:csp_course_pages_mode_desc'] = 'Opcjonalny nagłówek CSP na stronach kursu, na których działa widżet Asystenta kursu AI. <strong>Wyłączone</strong>: brak nagłówka (domyślnie). <strong>Tylko raportowanie</strong>: wysyła <code>Content-Security-Policy-Report-Only</code> — przeglądarki rejestrują naruszenia, ale ich nie blokują. Przydatne do tygodniowej obserwacji. <strong>Wymuszanie</strong>: wysyła <code>Content-Security-Policy</code> — przeglądarki blokują źródła ramek iframe spoza listy dozwolonych, żądania fetch i inne ryzykowne wczytania. Pomaga ograniczyć skutki dowolnych skryptów wklejonych do ustawienia witryny Additional HTML (incydent IBL AI / Raison z 2026-04-29). Nie dotyczy punktów końcowych [[tutorshort]], które zawsze wysyłają surowszy CSP.';
$string['settings:csp_mode_off'] = 'Wyłączone (brak nagłówka na stronach kursu)';
