// v4.6.0: vendor DPA gating + override editors.
$string['settings:vendor_data_heading'] = 'Dane dostawców i kosztów';
$string['settings:vendor_data_heading_desc'] = 'Sterowanie opcjonalną stroną administracyjną Vendor DPA oraz edytorami nadpisań, które pozwalają administratorom utrzymywać dołączoną tabelę dostawców i taryfę LLM w aktualnym stanie bez zmiany w kodzie. Oba edytory nadpisań działają na formacie JSON; pusta wartość powoduje powrót do wartości domyślnych zaszytych we wtyczce.';
$string['settings:vendor_dpa_admin_page_enabled'] = 'Pokaż stronę administracyjną Vendor DPA';
