$string['settings:talking_avatar_heading'] = 'Mówiący awatar';
$string['settings:talking_avatar_heading_desc'] = 'Wybierz, którego dostawcę mówiącego awatara [[tutorshort]] otwiera studentom, gdy powierzchnia awatara jest włączona. [[tutorshort]] dostarcza sterowniki dla D-ID (najtańszy streaming WebRTC), HeyGen (interaktywne awatary oparte na LiveKit), Tavus (gotowy do osadzenia w ramce iframe Conversational Video Interface) oraz Synthesia Agents (produkt agentowy działający w czasie rzeczywistym, konfigurowany w panelu Synthesia). Klucz i identyfikator persony dla poszczególnych dostawców znajdują się poniżej; wypełnić trzeba tylko wybranego dostawcę. Każde wywołanie wychodzące jest sprawdzane pod kątem SSRF.';
$string['settings:talking_avatar_provider'] = 'Dostawca mówiącego awatara';
$string['settings:talking_avatar_provider_desc'] = 'Wybierz dostawcę, którego klucz i identyfikator persony są wypełnione poniżej. Pozostaw wartość <em>Brak</em>, dopóki instytucja nie wyrazi zgody; domyślne ustawienie pedagogiczne nadal pojawia się w sekcji <em>Domyślne ustawienia pedagogiczne</em>, ale widżet pokazuje komunikat o konfiguracji zamiast awatara.';
$string['settings:talking_avatar_provider_none'] = 'Brak (awatar wyłączony)';
$string['settings:talking_avatar_provider_did'] = 'D-ID Streaming Talks';
$string['settings:talking_avatar_provider_heygen'] = 'HeyGen Interactive Avatar';
$string['settings:talking_avatar_provider_tavus'] = 'Tavus Conversational Video';
$string['settings:talking_avatar_provider_synthesia'] = 'Synthesia Agents (w czasie rzeczywistym)';
$string['settings:talking_avatar_did_api_key'] = 'Klucz API D-ID';
$string['settings:talking_avatar_did_api_key_desc'] = 'Ciąg <code>email:api-key</code> zakodowany w Base64, pobrany z <a href="https://studio.d-id.com/account-settings" target="_blank" rel="noopener">D-ID Studio → Account → API keys</a>. Wysyłany jako <code>Authorization: Basic …</code>.';
$string['settings:talking_avatar_did_persona_id'] = 'URL obrazu źródłowego D-ID';
$string['settings:talking_avatar_did_persona_id_desc'] = 'Publiczny adres HTTPS nieruchomego obrazu, który animuje D-ID (albo adres prezentera ze Studio, na przykład <code>https://create-images-results.d-id.com/…</code>). Wymagany dla każdego strumienia.';
$string['settings:talking_avatar_heygen_api_key'] = 'Klucz API HeyGen';
$string['settings:talking_avatar_heygen_api_key_desc'] = 'Klucz API z <a href="https://app.heygen.com/settings?nav=API" target="_blank" rel="noopener">HeyGen → Settings → API</a>. Wysyłany jako <code>X-Api-Key</code>.';
