$string['settings:talking_avatar_tavus_persona_id'] = 'Identyfikator repliki Tavus';
$string['settings:talking_avatar_tavus_persona_id_desc'] = 'Identyfikator repliki (wytrenowanego wizerunku), jako która [[tutorshort]] ma prowadzić rozmowę. W razie potrzeby połącz go z identyfikatorem persony, dopisując ten drugi w polu klucza API; [[tutorshort]] przekaże dalej <code>persona_id</code>.';
