$string['settings:talking_avatar_synthesia_api_key_desc'] = 'Klucz API z <a href="https://app.synthesia.io/#/account/api" target="_blank" rel="noopener">Synthesia → Account → API</a>. Wysyłany w nagłówku <code>Authorization</code> (Synthesia przyjmuje surowy klucz).';
