$string['talking_avatar:bundle_required'] = 'Przeglądarka mówiącego awatara wymaga skonfigurowanego pakietu CDN [[tutorshort]]. Poproś administratora o ustawienie adresu URL pakietu CDN w ustawieniach wtyczki.';
$string['talking_avatar:open'] = 'Otwórz awatara';
$string['talking_avatar:close'] = 'Zamknij awatara';
$string['settings:avatar_rate_card_overrides'] = 'Nadpisania taryfy awatarów (JSON)';
$string['settings:avatar_rate_card_overrides_desc'] = 'Obiekt JSON kluczowany dostawcą awatarów, z jedną stawką w USD za minutę. Zastępuje dołączoną stawkę dla tego dostawcy. Przykład: <pre>{ "did": 0.18, "heygen": 0.40, "tavus": 0.25 }</pre> Puste = użyj wartości domyślnych dołączonych w v4.10.0: D-ID 0,30 USD/min, HeyGen 0,50 USD/min, Tavus 0,30 USD/min, Synthesia 0,40 USD/min. Ustaw tutaj stawkę z Twojej umowy, aby panel analityczny odzwierciedlał rzeczywisty koszt instytucji.';
$string['settings:talking_avatar_did_webhook_secret'] = 'Sekret podpisywania webhooka D-ID';
$string['settings:talking_avatar_did_webhook_secret_desc'] = 'Opcjonalne. Po ustawieniu D-ID może wysyłać metodą POST zdarzenia zakończenia sesji pod adres <code>{wwwroot}/local/ai_course_assistant/talking_avatar_webhook.php?provider=did</code>, podpisane tym sekretem w nagłówku <code>X-DID-Signature</code> (szesnastkowy HMAC-SHA256). Wiersze z webhooka mają pierwszeństwo przed sygnałem heartbeat z frontendu. Puste = obsługa wyłączona, zakończeniem sesji zajmuje się wyłącznie heartbeat wraz z cogodzinnym zadaniem porządkującym.';
$string['settings:talking_avatar_heygen_webhook_secret'] = 'Sekret podpisywania webhooka HeyGen';
$string['settings:talking_avatar_heygen_webhook_secret_desc'] = 'Opcjonalne. Po ustawieniu HeyGen może wysyłać metodą POST zdarzenia zakończenia sesji, podpisane tym sekretem w nagłówku <code>X-HeyGen-Signature</code> (szesnastkowy HMAC-SHA256). Puste = obsługa wyłączona.';
$string['settings:talking_avatar_tavus_webhook_secret'] = 'Sekret podpisywania webhooka Tavus';
$string['settings:talking_avatar_tavus_webhook_secret_desc'] = 'Opcjonalne. Po ustawieniu Tavus może wysyłać metodą POST zdarzenia zakończenia rozmowy, podpisane tym sekretem w nagłówku <code>X-Tavus-Signature</code> (szesnastkowy HMAC-SHA256). Puste = obsługa wyłączona.';
$string['settings:talking_avatar_synthesia_webhook_secret'] = 'Sekret podpisywania webhooka Synthesia';
$string['settings:talking_avatar_synthesia_webhook_secret_desc'] = 'Opcjonalne. Po ustawieniu Synthesia może wysyłać metodą POST zdarzenia zakończenia sesji agenta, podpisane tym sekretem w nagłówku <code>X-Synthesia-Signature</code> (szesnastkowy HMAC-SHA256). Puste = obsługa wyłączona.';
