$string['settings:prompt_debug_enabled']      = 'Log assembled system prompt to file';
$string['settings:prompt_debug_enabled_desc'] = 'When on, every chat-turn writes the full assembled system prompt and per-section character counts to <code>moodledata/temp/sola_prompt_debug.log</code> (rolling at ~1MB). Default off. Use to measure prompt size empirically and audit which sections contribute the most tokens. The log contains the system prompt only (no learner input or PII).';
$string['settings:socratic_verbose'] = 'Rozbudowany prompt trybu sokratejskiego';
$string['settings:socratic_verbose_desc'] = 'Gdy włączone, kursy w trybie sokratejskim otrzymują pełną dyrektywę „rób / nie rób” o długości ok. 600 tokenów, pierwotnie dodaną w v3.9.30. Gdy wyłączone (domyślnie), otrzymują jednolinijkową dyrektywę, której nowoczesne modele hostowane trzymają się niezawodnie i która oszczędza ok. 600 tokenów na turę. Włącz tę opcję, jeśli kurs działa na słabszym modelu hostowanym samodzielnie, który potrzebuje jawnego rusztowania.';
$string['settings:prompt_budget_chars'] = 'Budżet znaków promptu systemowego';
$string['settings:prompt_budget_chars_desc'] = 'Maximum total size of the assembled system prompt before the user message, in characters. The structured prompt builder organises sections by category (identity, course context, learner state, behaviour, markers, safety) and drops or truncates the lowest-priority sections when the budget is exceeded. Safety guidance is always preserved in full. Default 8,000 characters (~2,000 tokens). Lower values reduce per-turn cost; higher values allow more course content to land in-prompt.';
$string['settings:current_page_content_maxchars'] = 'Limit treści bieżącej strony (znaki)';
$string['settings:current_page_content_maxchars_desc'] = 'Maksymalna liczba znaków tekstu bieżącej strony wstrzykiwanych do monitu systemowego jako sekcja „Current Page Content”, gdy RAG jest wyłączony. Wartość domyślna 8,000 dobrze ugruntowuje pytania dotyczące konkretnej strony, pozostawiając jednocześnie budżet na strukturę i instrukcje. (Przy włączonym RAG strona jest natomiast ugruntowywana przez własne najtrafniejsze fragmenty, z preferencją bieżącej strony, więc ten limit nie obowiązuje.) Bardzo długa strona jest obcinana od początku do tej liczby znaków, więc końcówka wyjątkowo długiej strony może nie zostać zacytowana; włączenie RAG pozwala tego uniknąć. Witryny dbające o koszty mogą ograniczyć tę wartość niżej (np. 3,000-4,000). Ograniczone do zakresu 500-8,000. Niezależne od <code>prompt_budget_chars</code>: ogranicza wyłącznie sekcję strony; budżet ogranicza cały monit.';
$string['settings:prompt_verbosity'] = 'Szczegółowość promptu';
$string['settings:prompt_verbosity_desc'] = 'Domyślna szczegółowość bloków instrukcji (tryb sokratejski, zasoby zewnętrzne). Zwięzła (domyślna) jest tym, czego nowoczesne modele hostowane trzymają się niezawodnie; standardowa dodaje jawne rusztowanie dla modeli średniej klasy; rozbudowana zachowuje obszerne wytyczne z czasów v3.9.30 dla słabszych modeli hostowanych samodzielnie. Nadpisanie dla poszczególnych kursów jest dostępne przez <code>prompt_verbosity_course_&lt;id&gt;</code>.';
$string['settings:prompt_verbosity_concise'] = 'Zwięzła (zalecana dla modeli hostowanych)';
$string['settings:prompt_verbosity_standard'] = 'Standardowa';
$string['settings:prompt_verbosity_verbose'] = 'Rozbudowana (dla słabszych modeli hostowanych samodzielnie)';
$string['settings:prompt_metrics_enabled'] = 'Zbieraj metryki promptu dla poszczególnych sekcji';
$string['settings:prompt_metrics_enabled_desc'] = 'Gdy włączone (domyślnie), każda tura czatu zapisuje jedną linię JSON na każdy złożony prompt do pliku <code>moodledata/sola_prompt_metrics/YYYY-MM-DD.log</code>, wraz z liczbą znaków w każdej kategorii. Przechowywane jest ostatnie 7 dni. Strona administracyjna metryk agreguje te dane na potrzeby rekomendacji budżetu. Nie są zapisywane żadne dane osobowe — wyłącznie rozmiary sekcji. Wyłącz, jeśli Twoja instytucja w ogóle nie chce pliku metryk.';
$string['settings:prompt_budget_auto_tune'] = 'Codzienne automatyczne dostrajanie budżetu promptu systemowego (wycofane)';
$string['settings:prompt_budget_auto_tune_desc'] = 'Wycofane. Nic nie robi, chyba że tryb budżetu powyżej jest ustawiony na <strong>Stały</strong>. Codzienne zadanie wnioskowało budżet znaków, obserwując przycinanie i goniąc największy prompt, jaki widziało. Wyprowadzenie budżetu z okna kontekstu modelu robi to lepiej: nie oscyluje i nie potrzebuje danych rozruchowych. Oba rozwiązania również kolidowały, bo zadanie zapisuje budżet znaków, a każda wartość inna niż domyślna wyłącza budżet wyprowadzony. Zostaw to wyłączone; zostanie usunięte w przyszłej wersji. Rekomendacja nadal pojawia się na stronie <a href="/local/ai_course_assistant/prompt_metrics.php">Metryki promptu</a>.';
$string['task:auto_tune_prompt_budget'] = 'Automatycznie dostrój budżet promptu [[tutorshort]] na podstawie obserwowanych metryk';
$string['prompt_metrics:title'] = 'Metryki promptu + rekomendacja budżetu';
$string['prompt_metrics:subtitle'] = 'Rozmiary promptu w podziale na sekcje, zebrane w ciągu ostatnich 7 dni. Służą do zaproponowania wartości ustawienia Budżet znaków promptu systemowego.';
$string['prompt_metrics:no_data'] = 'Nie zarejestrowano jeszcze żadnych metryk promptu. Wyślij kilka tur czatu z konta uczącego się, a następnie odśwież tę stronę. (Jeśli zbieranie metryk jest wyłączone w ustawieniach wtyczki, dane nie będą się gromadzić.)';
