$string['task:milestone_check'] = 'Wysyłaj codzienne e-maile z refleksją o kamieniach milowych (v5.3.0)';
$string['task:struggle_signal_review'] = 'Przetwórz sygnały trudności do prywatnej pamięci uczącego się (v5.3.0)';
$string['empathy:title'] = 'Komunikacja empatyczna i pamięć przenoszona (v5.3.0)';
$string['empathy:desc'] = 'Trzy powiązane funkcje, dzięki którym [[tutorshort]] bardziej przypomina trenera, który słucha. Cele zapisują, po co uczący się tu przyszedł. Pamięć przenoszona zapamiętuje, co wcześniej sprawiało trudność, dzięki czemu [[tutorshort]] może zaproponować inne podejście. Kamienie milowe świętują serie i ukończenia kursu e-mailem. Każda funkcja ma niezależny wyłącznik awaryjny i wymaga zgody uczącego się. Sygnały trudności nigdy nie opuszczają czatu — o trudnej sesji nigdy nie jest wysyłany żaden e-mail.';
$string['empathy:outreach_master_enabled'] = 'Główny wyłącznik awaryjny wysyłek';
$string['empathy:outreach_master_enabled_desc'] = 'Domyślnie wyłączone na świeżej instalacji. Gdy jest wyłączone, ŻADEN empatyczny e-mail jakiegokolwiek rodzaju nigdy nie zostanie wysłany, niezależnie od przełączników poszczególnych funkcji poniżej. Włącz to dopiero po przejrzeniu domyślnych ustawień poszczególnych funkcji i procedury zgody uczącego się.';
$string['empathy:goals_enabled'] = 'Włącz rozmowy o celach zawodowych';
$string['empathy:goals_enabled_desc'] = 'Pozwala uczącym się dobrowolnie podać dwie krótkie odpowiedzi (po co tu są, kim chcą zostać), które zasilają personalizację. Tylko w czacie; bez e-maili. Można bezpiecznie zostawić włączone.';
$string['empathy:milestones_enabled'] = 'Włącz e-maile refleksyjne o kamieniach milowych';
$string['empathy:milestones_enabled_desc'] = 'Wysyła krótki, ciepły e-mail, gdy uczący się osiągnie 7-dniową serię, 30-dniową serię lub ukończy kurs. Wymaga głównego przełącznika powyżej oraz zgody danego uczącego się. Twardy limit: jeden e-mail na uczącego się na 7 dni, łącznie we wszystkich kanałach.';
$string['empathy:memory_enabled'] = 'Włącz przenoszoną pamięć personalizacji';
$string['empathy:memory_enabled_desc'] = 'Sprawia, że [[tutorshort]] przenosi między sesjami krótkie prywatne notatki o tym, co sprawiało uczącemu się trudność, dzięki czemu kolejna odpowiedź może zaproponować inne podejście. Z limitem (maks. 5 notatek na uczącego się w kursie, TTL 90 dni). Uczący się może je edytować. Nigdy nie są widoczne dla prowadzących.';
$string['empathy:struggle_enabled'] = 'Włącz klasyfikator trudności';
$string['empathy:struggle_enabled_desc'] = 'Domyślnie wyłączone. Sprawia, że [[tutorshort]] wykrywa utrzymującą się frustrację przez kilka kolejnych tur i po cichu zapisuje notatkę o punkcie zapalnym w przenoszonej pamięci powyżej. Wynik pozostaje wyłącznie w czacie; o sesji z trudnościami nigdy nie jest wysyłany e-mail. Dane sygnałowe są automatycznie usuwane po 7 dniach.';
$string['empathy:outreach_dryrun'] = 'Próbna wysyłka (zapis w dzienniku bez wysyłania)';
$string['empathy:outreach_dryrun_desc'] = 'Gdy włączone, zaplanowane zadanie kamieni milowych zapisuje wiersze audytu tak, jakby wysłało e-maile, ale w rzeczywistości nie wysyła ich do nikogo. Użyj tego na świeżej instalacji, aby sprawdzić logikę karencji i zgód przed uruchomieniem produkcyjnym.';
$string['goals:save'] = 'Zapisz moje cele';
