$string['emergency:cli_reference'] = 'Te same kontrolki są dostępne z powłoki dyżurnej:';
$string['emergency:flag_chat'] = 'Czat';
$string['emergency:flag_chat_desc'] = 'Zatrzymuje wszystkie wywołania AI w [[tutorshort]] — czat, quizy, fiszki i ocenianie — jednakowo dla uczących się, administratorów i zadań zaplanowanych. Widżet nadal się wyświetla, a uczący się widzą krótki komunikat o wstrzymaniu. Autotest zaplecza i kontrola stanu pozostają dostępne, aby sprawdzić dostawcę przed przywróceniem.';
$string['emergency:flag_voice'] = 'Głos';
$string['emergency:flag_voice_desc'] = 'Czyści aktywnego dostawcę głosu realtime (zachowanego do dokładnego przywrócenia). Czat tekstowy działa dalej.';
$string['emergency:flag_rag'] = 'RAG';
$string['emergency:flag_rag_desc'] = 'Wyłącza wyszukiwanie i indeksowanie. Czat działa dalej bez osadzenia w treści kursu.';
$string['emergency:flag_outreach'] = 'Komunikacja';
$string['emergency:flag_outreach_desc'] = 'Zatrzymuje e-maile z podsumowaniami, kamieni milowych i przypomnień. Czat nie jest dotknięty.';
$string['emergency:flag_all'] = 'GŁÓWNE WYŁĄCZENIE';
$string['emergency:flag_all_desc'] = 'Wyłącza cały plugin: widżet znika z każdej strony, zaplanowane zadania zatrzymują się, głos wyczyszczony, RAG wyłączony, komunikacja wyłączona. Najsilniejszy przełącznik — użyj przy incydencie bezpieczeństwa lub gdy [[tutorshort]] musi zostać natychmiast odłączona.';
$string['emergency:settings_link'] = 'Sterowanie awaryjne';
$string['emergency:settings_link_desc'] = 'Przełączniki wyłączania per-podsystem (czat / głos / RAG / komunikacja / główny) z rejestrowaniem audytu — webowy odpowiednik <code>admin/cli/emergency_disable.php</code>. Otwórz <a href="{$a}">Sterowanie awaryjne [[tutorshort]]</a>.';
$string['email_unsubscribe:done_title'] = 'Wypisano';
