$string['email_unsubscribe:invalid_title'] = 'Link do wypisania jest już nieważny';
$string['email_unsubscribe:invalid_body'] = 'Ten link do wypisania wygasł lub jest nieprawidłowy. Poszukaj nowszego e-maila od nas lub skontaktuj się z administratorem strony, aby zostać usuniętym ręcznie.';
$string['settings:prompt_proportions_heading'] = 'Proporcje sekcji podpowiedzi (v5.6.0)';
$string['settings:prompt_proportions_heading_desc'] = 'Przydziel budżet podpowiedzi systemowej do czterech segmentów: bezpieczeństwo + tożsamość, struktura kursu, treść kursu i bieżąca strona. Wagi to procenty sumujące się do 100. Empirycznie dostrojone wartości domyślne (10 / 10 / 40 / 40) pochodzą z wzorca dostrajania wag v5.6.0; pozostawienie pola tekstowego pustego stosuje te wartości domyślne. Automatyczne wzmocnienie dostosowuje alokację per-tura w zależności od tego, czy bieżąca strona jest w zakresie.';
$string['settings:prompt_section_weights'] = 'Podstawowe wagi sekcji (JSON)';
$string['settings:prompt_section_weights_desc'] = 'Opcjonalny obiekt JSON mapujący każdy segment do wartości procentowej. Zostaw puste, aby użyć wzorcowych wartości domyślnych (10 / 10 / 40 / 40). Przykład: <code>{"safety_identity": 10, "course_structure": 10, "course_content": 40, "current_page": 40}</code>. Wagi muszą sumować się do 100 (±5%). <code>safety_identity</code> ma podłogę na poziomie 10%, aby odporność na jailbreak i znaczniki formatu wyjścia zawsze trafiały w pełni. <code>current_page + course_content</code> muszą wynosić co najmniej 40%, aby model miał merytoryczny materiał do zakotwiczenia. Wartości poza zakresem po cichu wracają do wzorcowych wartości domyślnych; administratorzy powinni weryfikować, sprawdzając dziennik debugowania podpowiedzi po zapisaniu.';
$string['settings:prompt_context_boost_mode'] = 'Tryb wzmocnienia kontekstu';
$string['settings:prompt_context_boost_mode_desc'] = 'Automatyczna korekta, która przesuwa wagę w kierunku sekcji bieżącej strony, gdy konkretna strona jest w zakresie, i w kierunku treści kursu, gdy żadna strona nie jest wybrana. <strong>page_focus</strong> (domyślnie) przesuwa ok. 15 punktów wagowych. <strong>aggressive</strong> przesuwa 25 punktów i jest najlepszy, gdy uczniowie konsekwentnie zadają pytania dotyczące konkretnych stron. <strong>off</strong> wyłącza wzmocnienie; ustawione przez administratora wagi podstawowe obowiązują w każdej turze niezależnie od kontekstu strony.';
$string['settings:prompt_context_boost_off'] = 'Wyłączone (stosuj wagi podstawowe w każdej turze)';
$string['settings:prompt_context_boost_page_focus'] = 'Fokus strony (domyślnie, ~15 punktów przesunięcia)';
$string['settings:prompt_context_boost_aggressive'] = 'Agresywny (~25 punktów przesunięcia)';
$string['settings:prompt_section_weights_coach'] = 'Nadpisanie w trybie coach (JSON, opcjonalne)';
$string['settings:prompt_section_weights_coach_desc'] = 'Opcjonalny obiekt JSON nadpisujący podstawowe wagi sekcji specyficznie podczas trybu coachingowego ocenianego quizu (gdy <code>quizmode=coach</code>). Przydatny do wymuszenia cięższej alokacji <code>current_page</code> podczas quizów bez wpływania na normalny czat. Zostaw puste, aby dziedziczyć wagi podstawowe. Te same reguły walidacji co ustawienie podstawowe.';
$string['prompt_debug_view:title'] = 'Przeglądarka dziennika debugowania podpowiedzi';
$string['prompt_debug_view:subtitle'] = 'Podpowiedź systemowa złożona per-tura + podział per-sekcja + historia konwersacji + bieżąca wiadomość użytkownika + metadane załącznika, dokładnie tak jak model je otrzymał. Użyj tego, aby sprawdzić, czy sekcja taka jak Treść bieżącej strony faktycznie trafiła do podpowiedzi oraz do debugowania problemów z jakością odpowiedzi bez logowania się przez SSH na serwer.';
$string['prompt_debug_view:disabled'] = 'Rejestrowanie debugowania podpowiedzi jest aktualnie WYŁĄCZONE. Żadne nowe wpisy nie będą zapisywane, dopóki nie zostanie włączone.';
$string['prompt_debug_view:enable_link'] = 'Otwórz ustawienia pluginu, aby włączyć „Zapisuj złożoną podpowiedź systemową do pliku".';
$string['prompt_debug_view:no_log_yet'] = 'Brak pliku dziennika. Wyślij co najmniej jedną turę czatu po włączeniu dziennika debugowania; plik jest tworzony przy pierwszym zapisie.';
$string['prompt_debug_view:empty'] = 'Plik dziennika istnieje, ale jest pusty. Wyślij turę czatu i odśwież.';
