$string['settings:voice_providers_heading'] = 'Dostawcy głosu (Realtime, TTS, STT)';
$string['settings:voice_providers_heading_desc'] = 'Skonfiguruj jednego lub więcej dostawców API głosu. Te ustawienia są niezależne od dostawcy czatu powyżej oraz od dostawcy osadzeń RAG — głos ma własną listę dostawców, ponieważ obecnie tylko OpenAI i xAI udostępniają punkty końcowe Realtime przez WebSocket oraz TTS i STT. Za pomocą list poniżej wybierz, który zarejestrowany dostawca obsługuje każdą z funkcji. Jeśli nie zdefiniowano żadnych wierszy, używany jest starszy mechanizm pojedynczego klucza (klucz API Realtime powyżej albo główny klucz OpenAI). Witryna korzystająca z Together AI / Anthropic / DeepSeek / Gemini / Mistral do czatu musi skonfigurować tu co najmniej jeden wiersz, aby głos działał.';
$string['settings:voice_active_realtime'] = 'Aktywny dostawca Realtime';
$string['settings:voice_active_realtime_desc'] = 'Który skonfigurowany dostawca głosu obsługuje sesje agenta głosowego Realtime.';
$string['settings:voice_active_tts'] = 'Aktywny dostawca TTS';
$string['settings:voice_active_tts_desc'] = 'Który skonfigurowany dostawca głosu odczytuje odpowiedzi AI na głos.';
$string['settings:voice_active_stt'] = 'Aktywny dostawca STT';
$string['settings:voice_active_stt_desc'] = 'Który dostawca zamienia mowę studentów na tekst. Pozostaw puste, aby preferować własny serwer Whisper, jeśli jest skonfigurowany poniżej, a następnie pierwszy wiersz dostawców głosu albo starszy klucz.';
$string['settings:stt_selfhosted_enabled'] = 'Włącz własną transkrypcję';
$string['settings:stt_selfhosted_enabled_desc'] = 'Używa własnego serwera Whisper opisanego poniżej jako ścieżki zamiany mowy na tekst dla wejścia głosowego i Soapbox. Wymaga podania adresu URL serwera poniżej. Po wyłączeniu transkrypcja wraca do ścieżki hostowanej (OpenAI Whisper) albo przeglądarkowej, nawet jeśli adres URL jest ustawiony.';
$string['settings:stt_selfhosted_warm'] = 'Rozgrzej przy rozpoczęciu nagrania Soapbox';
$string['settings:stt_selfhosted_warm_desc'] = 'Po włączeniu rozpoczęcie nagrania Soapbox wysyła lekkie żądanie rozgrzewające (w miarę możliwości) do własnego serwera transkrypcji, dzięki czemu host skalujący się do zera (na przykład Cloud Run) zdąży wystartować, gdy student jeszcze nagrywa — opóźnienie zimnego startu pozostaje wtedy niewidoczne dla transkrypcji uruchamianej przy wysyłaniu. Nie działa, jeśli powyżej nie podano adresu URL własnego serwera. Domyślnie wyłączone.';
$string['settings:voice_tab_enabled'] = 'Włącz kartę Głos';
$string['settings:voice_tab_enabled_desc'] = 'Pokazuje kartę Głos na dolnym pasku nawigacji. Po wyłączeniu studenci widzą tylko karty Czat i Notatki. Funkcje głosowe (ćwiczenie rozmowy, ćwiczenie wymowy) pozostają dostępne przez podpowiedzi rozpoczynające rozmowę, jeśli włączono je osobno.';
$string['settings:soapbox_heading'] = 'Soapbox';
