$string['settings:soapbox_max_recordings'] = 'Maksymalna liczba nagrań Soapbox na studenta i zadanie';
$string['settings:soapbox_max_recordings_desc'] = 'Bezwzględny górny limit liczby nagrań, jakie student może wykonać do jednego zadania, niezależnie od ustawienia liczby prób w zadaniu. Domyślnie 3.';
$string['settings:soapbox_retention_days'] = 'Okres przechowywania nagrań Soapbox (dni)';
$string['settings:soapbox_retention_days_desc'] = 'Jak długo nagranie jest przechowywane przed automatycznym usunięciem; transkrypcja, wynik i informacja zwrotna zostają zachowane. Ograniczone do 1–28 dni. Krócej znaczy lepsza minimalizacja danych. Domyślnie 7.';
$string['settings:soapbox_video_quality'] = 'Jakość wideo w Soapbox';
$string['settings:soapbox_video_quality_desc'] = 'Rozdzielczość i przepływność nagrania. To główny czynnik wpływający na koszt i przepustowość; osoba mówiąca w planie średnim jest dobrze czytelna w jakości standardowej. Niska nadaje się do słabych łączy; wysoka tylko wtedy, gdy liczą się szczegóły obrazu.';
$string['settings:soapbox_storage_bucket'] = 'Zasobnik magazynu Soapbox';
