$string['settings:bench_default_samples'] = 'Prompty na przebieg';
$string['settings:bench_default_samples_desc'] = 'Ile promptów wysyła benchmark dodany do kolejki z interfejsu www. Każdy prompt kosztuje dwa rzeczywiste wywołania modelu — odpowiedź i sędziego — więc to właśnie pokrętło kosztu. Ograniczone w kodzie do 50, co jest zarazem rozmiarem złotego zestawu i wartością utrzymującą jeden przebieg w limicie zapytań dostawcy.';
$string['settings:bench_heading'] = 'Benchmarki modeli';
$string['settings:bench_heading_desc'] = 'Przebieg benchmarku odpowiada na 50 promptów, a model sędziujący ocenia każdą odpowiedź według rubryki, po czym zapisywany jest jeden wiersz: średnia z rubryki, koszt wywołania i czas do pierwszego bajtu. Przebiegi są dodawane do kolejki ze strony rejestru modeli i wykonywane przez cron.';
$string['settings:bench_judge_model'] = 'Model sędziujący';
$string['settings:bench_judge_model_desc'] = 'Model, który ocenia odpowiedzi. Jego zmiana zmienia znaczenie każdej późniejszej oceny, dlatego każdy przebieg zapisuje użytego sędziego oraz wydanie wtyczki, na którym został uruchomiony.';
$string['settings:bench_judge_provider'] = 'Dostawca modelu sędziującego';
$string['settings:bench_judge_provider_desc'] = 'Dostawca modelu, który ocenia odpowiedzi. Trzymaj go poza pulą zawodników: model nie może oceniać samego siebie.';
$string['settings:bench_min_quality_n'] = 'Próg porównywalności (ocenione pozycje)';
$string['settings:bench_min_quality_n_desc'] = 'Najmniejsza liczba ocenionych pozycji, jaką może mieć zapisany przebieg i nadal być porównywany z innym przebiegiem. Przebiegi poniżej progu są zachowywane i pokazywane, oznaczone jako wyłącznie poglądowe, więc trzypromptowy przebieg smoke nigdy nie wyprzedzi wyniku z pięćdziesięciu promptów. Pozostaw 0, aby użyć wbudowanej wartości domyślnej; próg równy 0 zniweczyłby to zabezpieczenie.';
$string['settings:embed_input_type_asymmetric'] = 'Asymetryczny zapytanie/dokument (zalecany)';
$string['settings:embed_input_type_mode'] = 'Typ wejścia embeddingu';
$string['settings:embed_input_type_mode_desc'] = 'Tylko dla osadzeń Voyage. Voyage rzutuje tekst inaczej w zależności od tego, czy jest to zapytanie, czy dokument. „Asymetryczny” wysyła input_type=query przy wyszukiwaniu i input_type=document przy indeksowaniu. Tak zakłada dostawca i tak wypada najlepiej w pomiarach na tym korpusie: użycie projekcji dokumentu po stronie zapytania kosztowało 30,8 punktu procentowego recall i przegrało w każdym przedziale długości zapytania (2026-08-21, voyage-3.5, zestaw o kształcie produkcyjnym). „Wspólna przestrzeń” wysyła input_type=document po obu stronach; wyszukuje mierzalnie gorzej i istnieje wyłącznie jako ubezpieczenie migracji, ponieważ jedna projekcja pozwala zmienić model zapytań bez ponownego osadzania korpusu. Wybierz asymetryczny, chyba że jesteś w trakcie migracji. Zmiana nie wymaga reindeksacji: zmienia się tylko projekcja po stronie zapytania. To NIE jest asymetryczne parowanie modeli (indeksowanie większym modelem Voyage niż ten, którym odpytujesz) – to inna technika, która dwukrotnie nie dała się odtworzyć na tym korpusie, i steruje nią ustawienie modelu zapytań, a nie to.';
$string['settings:embed_input_type_shared'] = 'Wspólna przestrzeń (ubezpieczenie migracji; gorsze wyniki)';
$string['settings:embed_migration_heading'] = 'Migracja modelu embeddingu';
$string['settings:embed_migration_heading_desc'] = 'Zmiana modelu embeddingu lub jego szerokości unieważnia każdy zapisany wektor: mechanizm wyszukiwania odmawia oceniania zapytania wobec fragmentów z innej przestrzeni embeddingu, więc kurs nie zwraca nic, zamiast zwracać wyniki słabej jakości. Te ustawienia opisują model, DO którego przechodzisz. Kursy są następnie osadzane ponownie pojedynczo ze strony indeksu RAG, zapisując nowe wektory obok starych, a aktywne ustawienia powyżej nadal obsługują wyszukiwanie, dopóki nie zmienisz ich samodzielnie.';
$string['settings:embed_migration_provider_inherit'] = 'Użyj dostawcy skonfigurowanego powyżej';
$string['settings:embed_migration_target_apikey'] = 'Klucz API docelowego dostawcy';
$string['settings:embed_migration_target_apikey_desc'] = 'Potrzebny tylko wtedy, gdy docelowy dostawca różni się od skonfigurowanego powyżej. Puste oznacza użycie istniejącego klucza embeddingu.';
$string['settings:embed_migration_target_dimensions'] = 'Docelowa szerokość embeddingu';
$string['settings:embed_migration_target_dimensions_desc'] = 'Szerokość wektora żądana podczas migracji. 0 oznacza natywną szerokość modelu. Voyage przyjmuje 256, 512, 1024 i 2048; szerokość, której model nie oferuje, jest pomijana w żądaniu, a nie wysyłana — w przeciwnym razie po cichu otrzymałbyś szerokość natywną zamiast tej, o którą poprosiłeś.';
$string['settings:embed_migration_target_model'] = 'Docelowy model embeddingu';
$string['settings:embed_migration_target_model_desc'] = 'Nazwa modelu używanego do osadzania podczas migracji, na przykład <code>voyage-4-large</code>. Puste oznacza, że migracja nie jest skonfigurowana i strona indeksu RAG jej nie oferuje.';
$string['settings:embed_migration_target_provider'] = 'Docelowy dostawca embeddingu';
$string['settings:embed_migration_target_provider_desc'] = 'Pozostaw puste, aby migrować w ramach dostawcy już skonfigurowanego powyżej.';
$string['settings:rerank_min_query_chars'] = 'Rerank: minimalna długość zapytania';
$string['settings:rerank_min_query_chars_desc'] = 'Pomiń re-ranker dla zapytań o tej długości w znakach lub krótszych. Krótkie zapytania mają charakter słów kluczowych, a re-ranker prawie nic nie wnosi ponad podobieństwo cosinusowe na dwóch czy trzech słowach. Zmierzone na zestawie fixtures RAG: bramkowanie przy 50 dało 67,7% recall wobec 67,2% przy zawsze włączonym, przy około jednej trzeciej kosztu. Ustaw 0, aby re-rankować każde zapytanie. Pominięte re-rankingi są zapisywane w dzienniku wiadomości jako „[Rerank skipped: short_query]”, aby można było potwierdzić, że bramka działa.';
$string['settings:spend_export_key'] = 'Klucz eksportu wydatków';
$string['settings:spend_export_key_desc'] = 'Klucz Bearer dla miesięcznego punktu końcowego eksportu wydatków na AI pod adresem <code>/local/ai_course_assistant/spend_export.php</code>, z którego panel wydatków pobiera dane raz w miesiącu. Pozostaw puste, aby wyłączyć ten punkt końcowy — zwraca on wtedy 404 na każde żądanie. Klucz jest przyjmowany WYŁĄCZNIE w nagłówku <code>Authorization: Bearer</code>, nigdy w adresie URL. Wygeneruj długą losową wartość; każdy, kto ją posiada, może odczytać wydatki na AI całej witryny. Każdy udany eksport jest zapisywany w dzienniku audytu wtyczki.';
$string['task:migrate_course_embeddings'] = 'Migracja jednego kursu do nowego modelu embeddingu';
