$string['privacy:metadata:bench'] = 'Uruchomienia testów porównawczych dostawców: wyniki porównania modeli wygenerowane przez administratora witryny. Jedynymi danymi osobowymi jest identyfikator administratora, który uruchomił test. Te wiersze są konfiguracją witryny, a nie danymi osobowymi uczącego się, dlatego nie są uwzględniane w eksporcie danych ani usuwane, gdy użytkownik żąda usunięcia danych.';
$string['privacy:metadata:bench:createdby'] = 'Administrator witryny, który uruchomił ten test porównawczy. Puste, gdy test uruchomiono z wiersza poleceń.';
$string['privacy:metadata:models'] = 'Wpisy rejestru modeli: nadpisania cen i możliwości poszczególnych modeli, utrzymywane przez administratora witryny. Jedynymi danymi osobowymi jest identyfikator administratora, który ostatnio zapisał wpis. Te wiersze są konfiguracją witryny, a nie danymi osobowymi uczącego się, dlatego nie są uwzględniane w eksporcie danych ani usuwane, gdy użytkownik żąda usunięcia danych.';
$string['privacy:metadata:models:addedby'] = 'Administrator witryny, który ostatnio zapisał ten wpis rejestru modeli. Puste, gdy wpis został utworzony przez automatyczny kanał cenowy.';
$string['privacy:metadata:pricesrc'] = 'Definicje kanałów cenowych: cenniki dostawców, które administrator witryny skonfigurował do pobierania przez wtyczkę. Jedynymi danymi osobowymi jest identyfikator administratora, który dodał kanał. Te wiersze są konfiguracją witryny, a nie danymi osobowymi uczącego się, dlatego nie są uwzględniane w eksporcie danych ani usuwane, gdy użytkownik żąda usunięcia danych.';
$string['privacy:metadata:pricesrc:addedby'] = 'Administrator witryny, który dodał ten kanał cenowy. Puste, gdy kanał jest dostarczany wraz z wtyczką.';
$string['privacy:metadata:sbx_assign'] = 'Zadania prezentacji Soapbox: zadania konfigurowane przez nauczyciela dla kursu. Jedynymi danymi osobowymi jest identyfikator pracownika, który ostatnio edytował zadanie. Te wiersze są konfiguracją kursu, a nie danymi osobowymi uczącego się, dlatego nie są uwzględniane w eksporcie danych ani usuwane, gdy użytkownik żąda usunięcia danych, co w przeciwnym razie zmieniłoby zadanie, nad którym wciąż pracują inni uczący się.';
